  logger.info({ encodedToken });

  let payload: JwtPayload;
  try {
    payload = jwt.verify(encodedToken, JWT_SECRET) as JwtPayload;
  } catch (e) {

Server refuses to brew (verify) coffee (jwts) with a teapot (random strings)
