    'ai-data-scientist',
    'postgresql-dba',
    'blockchain',
    'qa',
    'software-architect',
    'cyber-security',
    'ux-design',
    'game-developer',
    'server-side-game-developer',
    'technical-writer',
    'mlops',
    'computer-science',
    'react',
    'vue',
    'javascript',
    'angular',
    'nodejs',
    'typescript',
    'python',
    'sql',
    'system-design',
    'aspnet-core',
    'java',
    'cpp',
    'docker',
    'prompt-engineering',
    'aws',
    'datastructures-and-algorithms',
    'kubernetes',
    'linux',
    'software-design-architecture',
    'rust',
    'react-native',
    'graphql',
    'spring-boot',
    'mongodb',
    'flutter',
    'design-system',
    'golang',
  ];

  if (!migratedRoadmaps.includes(resourceId)) {
    return;
  }

  const userId = getUser()?.id;
  if (!userId) {
    return;
  }

  const roadmapKey = `${resourceType}-${resourceId}-${userId}-progress`;
  const clearedKey = `${resourceType}-${resourceId}-${userId}-cleared`;

  const clearedCount = parseInt(localStorage.getItem(clearedKey) || '0', 10);

  if (clearedCount >= 10) {
    return;
  }

  localStorage.removeItem(roadmapKey);
  localStorage.setItem(clearedKey, `${clearedCount + 1}`);
}

